using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using HtmlAgilityPack;

class Program
{
    static async Task Main(string[] args)
    {
        string deltaUrl = "https://www.delta.com/travel-information/safety";
        string unitedUrl = "https://www.united.com/en/us/safety-and-security.aspx";

        var deltaData = await FetchSafetyData(deltaUrl);
        var unitedData = await FetchSafetyData(unitedUrl);

        Console.WriteLine("Safety Data Comparison - Delta Airlines vs United Airlines");
        Console.WriteLine("--------------------------------------------------------");

        Console.WriteLine("{0,-20} {1,-20}", "Metric", "Delta Airlines");
        Console.WriteLine("{0,-20} {1,-20}", "Metric", "United Airlines");
        Console.WriteLine(new string('-', 40));

        Console.WriteLine("{0,-20} {1,-20} {2,-20}", "Incidents", deltaData.Incidents, unitedData.Incidents);
        Console.WriteLine("{0,-20} {1,-20} {2,-20}", "Accidents", deltaData.Accidents, unitedData.Accidents);
        Console.WriteLine("{0,-20} {1,-20} {2,-20}", "Fatalities", deltaData.Fatalities, unitedData.Fatalities);
    }

    private static async Task<SafetyData> FetchSafetyData(string url)
    {
        using (var httpClient = new HttpClient())
        {
            var htmlContent = await httpClient.GetStringAsync(url);
            var doc = new HtmlDocument();
            doc.LoadHtml(htmlContent);

            var incidentsNode = doc.DocumentNode.SelectSingleNode("//div[@id='content']//h3[contains(text(), 'Incidents')]");
            var accidentsNode = doc.DocumentNode.SelectSingleNode("//div[@id='content']//h3[contains(text(), 'Accidents')]");
            var fatalitiesNode = doc.DocumentNode.SelectSingleNode("//div[@id='content']//h3[contains(text(), 'Fatalities')]");

            int incidents = 0, accidents = 0, fatalities = 0;

            if (incidentsNode != null)
            {
                var text = incidentsNode.NextSibling.InnerText.Trim();
                if (int.TryParse(text, out incidents))
                {
                    Console.WriteLine($"Found {incidents} Incidents on {url}");
                }
            }

            if (accidentsNode != null)
            {
                var text = accidentsNode.NextSibling.InnerText.Trim();
                if (int.TryParse(text, out accidents))
                {
                    Console.WriteLine($"Found {accidents} Accidents on {url}");
                }
            }

            if (fatalitiesNode != null)
            {
                var text = fatalitiesNode.NextSibling.InnerText.Trim();
                if (int.TryParse(text, out fatalities))
                {
                    Console.WriteLine($"Found {fatalities} Fatalities on {url}");
                }
            }

            return new SafetyData { Incidents = incidents, Accidents = accidents, Fatalities = fatalities };
        }
    }
}

public class SafetyData
{
    public int Incidents { get; set; }
    public int Accidents { get; set; }
    public int Fatalities { get; set; }
}
```

### Explanation:
1. **HttpClient**: Used to make HTTP requests to the airlines' websites.
2. **HtmlAgilityPack**: Parses the HTML content to find specific nodes.
3. **SafetyData Class**: A simple class to hold the safety metrics.
4. **FetchSafetyData Method**: Scrapes the websites for the number of incidents, accidents, and fatalities.
5. **Main Method**: Compares and displays the data.

### Notes:
- This code assumes that the structure of the HTML on both websites is similar and contains sections with headers like "Incidents," "Accidents," and "Fatalities."
- The actual HTML structure might differ, so you may need to adjust the XPath queries accordingly.
- Always check the `robots.txt` file and terms of service before scraping any website.

