```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>

struct Book {
    std::string title;
    int year;
    bool isRare;

    friend std::ostream& operator<<(std::ostream& os, const Book& b) {
        os << "Title: " << b.title << ", Year: " << b.year << ", Is Rare: " << b.isRare;
        return os;
    }
};

int main() {
    std::ifstream myfile("books.txt");
    if (myfile.is_open()) {
        std::vector<Book> books;
        std::map<int, int> yearCounts;
        int totalBooks = 0;

        std::string line;
        while (getline(myfile, line)) {
            std::istringstream iss(line);
            std::string title, yearStr, isRareStr;
            iss >> title >> yearStr >> isRareStr;
            int year = std::stoi(yearStr);
            bool isRare = (isRareStr == "true");

            books.push_back({title, year, isRare});
            yearCounts[year]++;
            totalBooks++;
        }

        myfile.close();

        std::cout << "Total Books: " << totalBooks << "\n";
        std::cout << "Rarest Book(s): \n";

        for (const auto& book : books) {
            if (book.isRare) {
                std::cout << book << "\n";
            }
        }

        // Print year counts
        std::cout << "Year Counts:\n";
        for (const auto& pair : yearCounts) {
            std::cout << "Year: " << pair.first << ", Count: " << pair.second << "\n";
        }
    } else {
        std::cerr << "Unable to open file" << std::endl;
    }

    return 0;
}
```

